/* ─── 3D Drum Carousel ───────────────────────────────────────────────── */
const drumProducts = [...products, ...products];
const COUNT = drumProducts.length;
const ANGLE_STEP = 360 / COUNT;
const RADIUS = 380; // px — радиус барабана

function DrumCarousel({ lang }: { lang: "ru" | "kz" }) {
    const [rotation, setRotation] = useState(0);
    const [isDragging, setIsDragging] = useState(false);
    const dragStart = useRef<{ x: number; rot: number; time: number } | null>(null);
    const autoRef = useRef<ReturnType<typeof setInterval> | null>(null);
    const drumRef = useRef<HTMLDivElement>(null);

    const activeRaw = Math.round(-rotation / ANGLE_STEP);
    const active = ((activeRaw % COUNT) + COUNT) % COUNT;

    /* Auto-rotate */
    const startAuto = useCallback(() => {
        if (autoRef.current) clearInterval(autoRef.current);
        autoRef.current = setInterval(() => {
            setRotation(r => Math.round(r / ANGLE_STEP) * ANGLE_STEP - ANGLE_STEP);
        }, 4000);
    }, []);

    const stopAuto = useCallback(() => {
        if (autoRef.current) clearInterval(autoRef.current);
    }, []);

    useEffect(() => {
        startAuto();
        return () => stopAuto();
    }, [startAuto, stopAuto]);

    /* Mouse drag */
    const onMouseDown = (e: React.MouseEvent) => {
        stopAuto();
        setIsDragging(true);
        dragStart.current = { x: e.clientX, rot: rotation, time: Date.now() };
    };

    const handleMove = useCallback((clientX: number) => {
        if (!isDragging || !dragStart.current) return;
        const dx = clientX - dragStart.current.x;
        setRotation(dragStart.current.rot + dx * 0.4);
    }, [isDragging]);

    const handleEnd = useCallback((clientX: number) => {
        if (!isDragging || !dragStart.current) return;
        setIsDragging(false);
        const dx = clientX - dragStart.current.x;
        const dt = Date.now() - dragStart.current.time;

        let finalRot = dragStart.current.rot + dx * 0.4;

        // Adds extra rotation based on swiftness of swipe
        if (dt > 10 && dt < 400 && Math.abs(dx) > 30) {
            const v = dx / dt;
            finalRot += v * 150;
        }

        const snappedRot = Math.round(finalRot / ANGLE_STEP) * ANGLE_STEP;
        setRotation(snappedRot);
        startAuto();
        dragStart.current = null;
    }, [isDragging, startAuto]);

    const onMouseMove = useCallback((e: MouseEvent) => handleMove(e.clientX), [handleMove]);
    const onMouseUp = useCallback((e: MouseEvent) => handleEnd(e.clientX), [handleEnd]);

    /* Touch drag */
    const onTouchStart = (e: React.TouchEvent) => {
        stopAuto();
        setIsDragging(true);
        dragStart.current = { x: e.touches[0].clientX, rot: rotation, time: Date.now() };
    };
    const onTouchMove = (e: React.TouchEvent) => handleMove(e.touches[0].clientX);
    const onTouchEnd = (e: React.TouchEvent) => handleEnd(e.changedTouches[0].clientX);

    useEffect(() => {
        if (isDragging) {
            window.addEventListener("mousemove", onMouseMove);
            window.addEventListener("mouseup", onMouseUp);
        }
        return () => {
            window.removeEventListener("mousemove", onMouseMove);
            window.removeEventListener("mouseup", onMouseUp);
        };
    }, [isDragging, onMouseMove, onMouseUp]);

    /* Manual nav */
    const goTo = (idx: number) => {
        stopAuto();
        let diff = (idx - active + COUNT) % COUNT;
        if (diff > COUNT / 2) diff -= COUNT;
        const snappedRot = Math.round(rotation / ANGLE_STEP) * ANGLE_STEP;
        setRotation(snappedRot - diff * ANGLE_STEP);
        setTimeout(startAuto, 4000);
    };

    return (
        <div className="relative flex flex-col items-center select-none min-h-[480px] sm:min-h-[550px] md:min-h-[680px] justify-center w-full">
            {/* Scene */}
            <div
                ref={drumRef}
                className="relative w-full flex items-center justify-center scale-[0.65] sm:scale-[0.8] md:scale-100 origin-center transition-transform duration-500"
                style={{ height: 440, cursor: isDragging ? "grabbing" : "grab", perspective: "1100px" }}
                onMouseDown={onMouseDown}
                onTouchStart={onTouchStart}
                onTouchMove={onTouchMove}
                onTouchEnd={onTouchEnd}
            >
                {/* Ground glow */}
                <div className="absolute bottom-0 left-1/2 -translate-x-1/2 w-96 h-20 pointer-events-none"
                    style={{ background: "radial-gradient(ellipse 80% 100% at 50% 100%, rgba(59,130,246,0.18) 0%, transparent 80%)" }} />

                {/* Drum */}
                <div
                    style={{
                        transformStyle: "preserve-3d",
                        transform: `rotateY(${rotation}deg)`,
                        transition: isDragging ? "none" : "transform 0.8s cubic-bezier(0.22,1,0.36,1)",
                        position: "relative",
                        width: 0,
                        height: 0,
                    }}
                >
                    {drumProducts.map((p, i) => {
                        const angle = i * ANGLE_STEP;
                        const isActive = active === i;
                        const curRot = rotation % 360;
                        const cardRot = (angle + curRot) % 360;
                        const norm = (cardRot + 360) % 360;
                        // Show all parts of the drum
                        const hidden = false;

                        return (
                            <div
                                key={i}
                                onClick={() => !isDragging && goTo(i)}
                                style={{
                                    position: "absolute",
                                    width: 180,
                                    left: -90,
                                    top: -165,
                                    transformStyle: "preserve-3d",
                                    transform: `rotateY(${angle}deg) translateZ(${RADIUS}px)`,
                                    transition: "opacity 0.6s ease, visibility 0.6s ease",
                                    cursor: isActive ? "default" : "pointer",
                                    backfaceVisibility: "hidden",
                                    WebkitBackfaceVisibility: "hidden",
                                    visibility: hidden ? "hidden" : "visible",
                                    opacity: hidden ? 0 : 1,
                                }}
                            >
                                <div
                                    style={{
                                        background: isActive
                                            ? `linear-gradient(145deg, rgba(7,28,82,0.8), rgba(2,13,43,0.8))`
                                            : "transparent",
                                        border: isActive
                                            ? `2px solid rgba(${p.accentRgb},0.8)`
                                            : "1px solid rgba(255,255,255,0.05)",
                                        borderRadius: 16,
                                        padding: "16px 12px",
                                        backdropFilter: "blur(20px)",
                                        boxShadow: isActive
                                            ? `0 0 0 0px rgba(${p.accentRgb},0.3), 0 24px 60px -12px rgba(${p.accentRgb},0.5), inset 0 1px 0 rgba(255,255,255,0.12), 0 0 30px -8px rgba(${p.accentRgb},0.35)`
                                            : "0 6px 20px rgba(0,0,0,0.3)",
                                        opacity: isActive ? 1 : 0.4,
                                        transform: isActive ? "scale(1.1)" : "scale(0.9)",
                                        transition: "all 0.7s cubic-bezier(0.22,1,0.36,1)",
                                        width: "100%",
                                        height: 330,
                                        margin: "0 auto",
                                        display: "flex",
                                        flexDirection: "column",
                                        position: "relative",
                                        overflow: "hidden",
                                        animation: isActive ? "cardGlowPulse 2.5s ease-in-out infinite" : "none",
                                        backfaceVisibility: "hidden",
                                        WebkitBackfaceVisibility: "hidden",
                                    }}
                                >
                                    {/* Shimmer sweep on activate */}
                                    {isActive && (
                                        <div style={{
                                            position: "absolute", top: 0, left: "-80%",
                                            width: "60%", height: "100%",
                                            background: `linear-gradient(120deg, transparent 0%, rgba(${p.accentRgb},0.12) 50%, transparent 100%)`,
                                            animation: "shimmerSlide 2s ease-in-out infinite",
                                            pointerEvents: "none",
                                            borderRadius: 28,
                                        }} />
                                    )}
                                    {/* Corner accent lines */}
                                    {isActive && (
                                        <>
                                            <div style={{ position: "absolute", top: 12, left: 12, width: 28, height: 28, borderTop: `2px solid ${p.accent}`, borderLeft: `2px solid ${p.accent}`, borderRadius: "6px 0 0 0", pointerEvents: "none" }} />
                                            <div style={{ position: "absolute", top: 12, right: 12, width: 28, height: 28, borderTop: `2px solid ${p.accent}`, borderRight: `2px solid ${p.accent}`, borderRadius: "0 6px 0 0", pointerEvents: "none" }} />
                                            <div style={{ position: "absolute", bottom: 12, left: 12, width: 28, height: 28, borderBottom: `2px solid ${p.accent}`, borderLeft: `2px solid ${p.accent}`, borderRadius: "0 0 0 6px", pointerEvents: "none" }} />
                                            <div style={{ position: "absolute", bottom: 12, right: 12, width: 28, height: 28, borderBottom: `2px solid ${p.accent}`, borderRight: `2px solid ${p.accent}`, borderRadius: "0 0 6px 0", pointerEvents: "none" }} />
                                        </>
                                    )}

                                    {/* Badge */}
                                    <div className="mb-2">
                                        <span
                                            className="inline-block text-[9px] font-bold tracking-[0.14em] uppercase rounded-full px-3 py-1"
                                            style={{ border: `1px solid ${p.accent}60`, color: p.accent, background: `${p.accent}12` }}
                                        >
                                            {p.badge[lang]}
                                        </span>
                                    </div>

                                    {/* Image */}
                                    <div className="flex items-center justify-center flex-1 my-1">
                                        <img
                                            src={p.img}
                                            alt={p.label[lang]}
                                            className="w-24 md:w-28 mb-2 object-contain"
                                            style={{
                                                filter: `drop-shadow(0 15px 30px rgba(${p.accentRgb},0.6))`,
                                                animation: isActive ? "drumFloat 4s ease-in-out infinite" : "none",
                                            }}
                                            draggable={false}
                                        />
                                    </div>

                                    {/* Text */}
                                    <div className="mt-1 text-center flex-shrink-0">
                                        <h2 className="text-[10px] font-black tracking-widest uppercase text-white mb-1 px-1 leading-tight">
                                            {p.label[lang]}
                                        </h2>
                                        <p className="text-[8px] text-white/40 leading-relaxed font-light px-2" style={{ minHeight: 36 }}>
                                            {p.desc[lang]}
                                        </p>
                                    </div>
                                </div>
                            </div>
                        );
                    })}
                </div>
            </div>

            {/* Dots + arrows */}
            <div className="flex items-center gap-5 mt-10">
                <button
                    onClick={() => goTo((active - 1 + COUNT) % COUNT)}
                    className="w-10 h-10 rounded-full border border-white/15 flex items-center justify-center text-white/40 hover:text-white hover:border-white/40 transition-all duration-200"
                >
                    <svg width="16" height="16" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
                        <path d="M10 12L6 8l4-4" />
                    </svg>
                </button>
                <div className="flex gap-2.5">
                    {products.map((p, i) => {
                        const isDotActive = (active % products.length) === i;
                        return (
                            <button
                                key={i}
                                onClick={() => {
                                    stopAuto();
                                    const currentMod = active % products.length;
                                    let diff = i - currentMod;
                                    if (diff > products.length / 2) diff -= products.length;
                                    if (diff < -products.length / 2) diff += products.length;
                                    const snappedRot = Math.round(rotation / ANGLE_STEP) * ANGLE_STEP;
                                    setRotation(snappedRot - diff * ANGLE_STEP);
                                    setTimeout(startAuto, 4000);
                                }}
                                style={{
                                    width: isDotActive ? 24 : 8,
                                    height: 8,
                                    borderRadius: 9999,
                                    background: isDotActive ? p.accent : "rgba(255,255,255,0.2)",
                                    transition: "all 0.4s cubic-bezier(0.22,1,0.36,1)",
                                    border: "none",
                                    cursor: "pointer",
                                    padding: 0,
                                }}
                            />
                        );
                    })}
                </div>
                <button
                    onClick={() => goTo((active + 1) % COUNT)}
                    className="w-10 h-10 rounded-full border border-white/15 flex items-center justify-center text-white/40 hover:text-white hover:border-white/40 transition-all duration-200"
                >
                    <svg width="16" height="16" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
                        <path d="M6 4l4 4-4 4" />
                    </svg>
                </button>
            </div>

            {/* Hint */}
            <p className="mt-4 text-[10px] text-white/20 tracking-[0.25em] uppercase">
                {lang === "ru" ? "Перетащите или нажмите" : "Сүйреп немесе басыңыз"}
            </p>
        </div>
    );
}

